ALTER TABLE "Vaccine" ADD COLUMN "diluentMaterialId" TEXT REFERENCES "Material"(id) ON DELETE RESTRICT ON UPDATE CASCADE, ADD COLUMN "diluentUnitsPerVial" DOUBLE PRECISION NOT NULL DEFAULT 1, ADD COLUMN "useAfterOpeningHours" DOUBLE PRECISION, ADD COLUMN "rndsAuthorized" BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE "HealthVaccineManufacturer" (id TEXT PRIMARY KEY,name TEXT NOT NULL,"rndsCode" TEXT UNIQUE,"sourceReference" TEXT,"isActive" BOOLEAN NOT NULL DEFAULT true,"actorUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "HealthVaccineCodeMapping" (id TEXT PRIMARY KEY,"vaccineId" TEXT NOT NULL REFERENCES "Vaccine"(id) ON DELETE RESTRICT ON UPDATE CASCADE,system TEXT NOT NULL,code TEXT NOT NULL,version TEXT NOT NULL,"sourceReference" TEXT NOT NULL,"actorUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("vaccineId",system,version));
CREATE TABLE "HealthVaccineLotProfile" ("stockId" TEXT PRIMARY KEY REFERENCES "MaterialStock"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"dosesPerVial" INTEGER NOT NULL,"manufacturerId" TEXT REFERENCES "HealthVaccineManufacturer"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"manufacturerName" TEXT,"actorUsuarioId" TEXT NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "HealthVaccineOpenedVial" (id TEXT PRIMARY KEY,"stockId" TEXT NOT NULL REFERENCES "MaterialStock"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"vaccineId" TEXT NOT NULL REFERENCES "Vaccine"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"openedAt" TIMESTAMP(3) NOT NULL,"expiresAt" TIMESTAMP(3),"remainingDoses" INTEGER NOT NULL,"totalDoses" INTEGER NOT NULL,"sourceReference" TEXT,"diluentStockId" TEXT REFERENCES "MaterialStock"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"diluentMovementId" TEXT UNIQUE,"actorUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "HealthVaccineOpenedVial_stockId_remainingDoses_idx" ON "HealthVaccineOpenedVial"("stockId","remainingDoses");
ALTER TABLE "HealthVaccineOpenedVial" ADD COLUMN adjustments JSONB NOT NULL DEFAULT '[]';
ALTER TABLE "HealthVaccineOpenedVial" ADD COLUMN "preparationKey" TEXT UNIQUE;
CREATE TABLE "HealthVaccineCalendarRule" (id TEXT PRIMARY KEY,code TEXT NOT NULL,version INTEGER NOT NULL,"vaccineId" TEXT NOT NULL REFERENCES "Vaccine"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"doseNumber" INTEGER NOT NULL,strategy TEXT NOT NULL,"ageUnit" TEXT NOT NULL,"minimumAge" INTEGER NOT NULL,"maximumAge" INTEGER,"minimumIntervalDays" INTEGER NOT NULL DEFAULT 0,"repeatEveryMonths" INTEGER,required BOOLEAN NOT NULL DEFAULT true,enabled BOOLEAN NOT NULL DEFAULT true,"validFrom" TIMESTAMP(3) NOT NULL,"validUntil" TIMESTAMP(3),"sourceReference" TEXT NOT NULL,"actorUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(code,version));
CREATE INDEX "HealthVaccineCalendarRule_vaccineId_doseNumber_strategy_idx" ON "HealthVaccineCalendarRule"("vaccineId","doseNumber",strategy);
CREATE TABLE "HealthVaccineInteraction" (id TEXT PRIMARY KEY,"firstVaccineId" TEXT NOT NULL REFERENCES "Vaccine"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"secondVaccineId" TEXT NOT NULL REFERENCES "Vaccine"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"minimumIntervalDays" INTEGER NOT NULL,"allowSameDay" BOOLEAN NOT NULL DEFAULT false,"sourceReference" TEXT NOT NULL,"actorUsuarioId" TEXT NOT NULL,UNIQUE("firstVaccineId","secondVaccineId"));
CREATE TABLE "HealthVaccinationCampaign" (id TEXT PRIMARY KEY,name TEXT NOT NULL,"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3) NOT NULL,"publicInformation" TEXT NOT NULL,"actorUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "HealthVaccinationCardEvent" (id TEXT PRIMARY KEY,"patientId" TEXT NOT NULL REFERENCES "Patient"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"vaccineId" TEXT NOT NULL REFERENCES "Vaccine"(id) ON DELETE RESTRICT ON UPDATE CASCADE,kind TEXT NOT NULL,"doseNumber" INTEGER NOT NULL,strategy TEXT NOT NULL,"occurredAt" TIMESTAMP(3) NOT NULL,"scheduledFor" TIMESTAMP(3),"until" TIMESTAMP(3),"professionalId" TEXT NOT NULL REFERENCES "HealthProfessional"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"unitId" TEXT NOT NULL REFERENCES "HealthUnit"(id) ON DELETE RESTRICT ON UPDATE CASCADE,reason TEXT NOT NULL,"sourceReference" TEXT,"lotNumber" TEXT,"revokedAt" TIMESTAMP(3),"revokedReason" TEXT,"revokedByUsuarioId" TEXT,"actorUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "HealthVaccinationCardEvent_patientId_vaccineId_kind_idx" ON "HealthVaccinationCardEvent"("patientId","vaccineId",kind);
ALTER TABLE "VaccinationRecord" ADD COLUMN "careGroup" TEXT, ADD COLUMN "actorUsuarioId" TEXT, ADD COLUMN "codeSnapshot" JSONB, ADD COLUMN "manufacturerId" TEXT REFERENCES "HealthVaccineManufacturer"(id) ON DELETE RESTRICT ON UPDATE CASCADE, ADD COLUMN "campaignId" TEXT REFERENCES "HealthVaccinationCampaign"(id) ON DELETE RESTRICT ON UPDATE CASCADE, ADD COLUMN "openedVialId" TEXT REFERENCES "HealthVaccineOpenedVial"(id) ON DELETE RESTRICT ON UPDATE CASCADE, ADD COLUMN "indicationEventId" TEXT UNIQUE REFERENCES "HealthVaccinationCardEvent"(id) ON DELETE RESTRICT ON UPDATE CASCADE, ADD COLUMN "appointmentId" TEXT REFERENCES "HealthAppointment"(id) ON DELETE RESTRICT ON UPDATE CASCADE, ADD COLUMN "medicalRecordId" TEXT REFERENCES "MedicalRecord"(id) ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "HealthVaccineAdverseEvent" (id TEXT PRIMARY KEY,"patientId" TEXT NOT NULL REFERENCES "Patient"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"vaccineId" TEXT NOT NULL REFERENCES "Vaccine"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"vaccinationRecordId" TEXT REFERENCES "VaccinationRecord"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"unitId" TEXT NOT NULL REFERENCES "HealthUnit"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"occurredAt" TIMESTAMP(3) NOT NULL,"eventType" TEXT NOT NULL,"lesionType" TEXT NOT NULL,"lesionLocation" TEXT NOT NULL,severity TEXT NOT NULL,"clinicalNotes" TEXT NOT NULL,"actorUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "HealthVaccineAdverseFollowup" (id TEXT PRIMARY KEY,"eventId" TEXT NOT NULL REFERENCES "HealthVaccineAdverseEvent"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"occurredAt" TIMESTAMP(3) NOT NULL,conduct TEXT NOT NULL,narrative TEXT NOT NULL,"professionalId" TEXT NOT NULL REFERENCES "HealthProfessional"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"actorUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE "HealthStockReceiptItem" ADD COLUMN "vaccineDosesPerVial" INTEGER, ADD COLUMN "vaccineManufacturerId" TEXT REFERENCES "HealthVaccineManufacturer"(id) ON DELETE RESTRICT ON UPDATE CASCADE;
